dt-example.js:
new DataTable('#example', {
	cardView: true,
	layout: {
		topStart: {
			buttons: [
				'stateCreate',
				'statesList',
				{
					extend: 'collection',
					text: 'Display mode',
					buttons: ['cardView', 'tableView', 'autoView']
				}
			]
		}
	},
	stateRestore: {
		include: {
			cardView: null
		}
	}
});
